from __future__ import annotations

from base64 import b64decode
from hashlib import sha256
import json
from pathlib import Path
from zlib import decompress

ROOT = Path(__file__).resolve().parents[1]
TARGET = ROOT / "PrimalitySheafVerification" / "Mock2_FunctionalAnalysis.lean"
EXPECTED_INPUT_SHA256 = "57f084029aff8e8a4b95d13e0daa9890eaa036716da48b3a3352ac3023be1c25"
EXPECTED_OUTPUT_SHA256 = "48707b6952a1aad8e19fd47b5f3d4f74d4e0b0e66262ead87386512786083c3e"
PAYLOAD = """"""


def digest(text: str) -> str:
    return sha256(text.encode("utf-8")).hexdigest()


def main() -> int:
    text = TARGET.read_text(encoding="utf-8")
    input_sha = digest(text)
    print(f"input_sha256={input_sha}")
    if input_sha == EXPECTED_OUTPUT_SHA256:
        print("[pass340] already applied")
        return 0
    if input_sha != EXPECTED_INPUT_SHA256:
        raise RuntimeError(
            f"unexpected pass340 input sha256: {input_sha}; "
            f"expected {EXPECTED_INPUT_SHA256}"
        )

    replacements = json.loads(decompress(b64decode(PAYLOAD)).decode("utf-8"))
    for item in replacements:
        old = item["old"]
        new = item["new"]
        count = text.count(old)
        print(f'{item["name"]}: expected=1 actual={count}')
        if count != 1:
            raise RuntimeError(
                f'{item["name"]}: expected one occurrence, found {count}'
            )
        text = text.replace(old, new)

    output_sha = digest(text)
    print(f"output_sha256={output_sha}")
    if output_sha != EXPECTED_OUTPUT_SHA256:
        raise RuntimeError(
            f"unexpected pass340 output sha256: {output_sha}; "
            f"expected {EXPECTED_OUTPUT_SHA256}"
        )
    TARGET.write_text(text, encoding="utf-8")
    print("[pass340] conjugation, dense-domain, closure, and directional frontiers repaired")
    return 0


if __name__ == "__main__":
    raise SystemExit(main())
